const listCancellationLineage = `-- name: ListCancellationLineage :many
WITH RECURSIVE lineage AS (
    SELECT runs.id,
           runs.parent_run_id,
           runs.parent_owns_lifecycle,
           0 AS depth,
           ARRAY[runs.id] AS path,
           false AS cycle,
           $1::integer AS max_depth
      FROM runs
     WHERE runs.id = $2
    UNION ALL
    SELECT parent.id,
           parent.parent_run_id,
           parent.parent_owns_lifecycle,
           lineage.depth + 1,
           lineage.path || parent.id,
           parent.id = ANY(lineage.path),
           lineage.max_depth
      FROM lineage
      JOIN runs AS parent
        ON parent.id = lineage.parent_run_id
     WHERE lineage.parent_owns_lifecycle IS TRUE
       AND NOT lineage.cycle
       AND lineage.depth < lineage.max_depth
)
SELECT id, depth, cycle
  FROM lineage
 ORDER BY depth DESC
`

type ListCancellationLineageParams struct {
	MaxDepth int32       `json:"max_depth"`
	TargetID pgtype.UUID `json:"target_id"`
}

type ListCancellationLineageRow struct {
	ID    pgtype.UUID `json:"id"`
	Depth int32       `json:"depth"`
	Cycle bool        `json:"cycle"`
}

func (q *Queries) ListCancellationLineage(ctx context.Context, arg ListCancellationLineageParams) ([]ListCancellationLineageRow, error) {
	rows, err := q.db.Query(ctx, listCancellationLineage, arg.MaxDepth, arg.TargetID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListCancellationLineageRow
	for rows.Next() {
		var i ListCancellationLineageRow
		if err := rows.Scan(&i.ID, &i.Depth, &i.Cycle); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listOwnedCancellationRuns = `-- name: ListOwnedCancellationRuns :many
WITH RECURSIVE owned AS (
    SELECT runs.id,
           0 AS depth,
           ARRAY[runs.id] AS path,
           false AS cycle,
           $2::integer AS max_depth
      FROM runs
     WHERE runs.id = $3
       AND runs.org_id = $4
       AND runs.project_id = $5
       AND runs.environment_id = $6
    UNION ALL
    SELECT child.id,
           owned.depth + 1,
           owned.path || child.id,
           child.id = ANY(owned.path),
           owned.max_depth
      FROM owned
      JOIN runs AS child
        ON child.parent_run_id = owned.id
       AND child.parent_owns_lifecycle IS TRUE
       AND child.org_id = $4
       AND child.project_id = $5
       AND child.environment_id = $6
       AND child.status IN ('queued', 'running', 'waiting', 'retry_delayed', 'cancel_requested')
     WHERE NOT owned.cycle
       AND owned.depth < owned.max_depth
)
SELECT id, depth, cycle
  FROM owned
 ORDER BY depth, id
 LIMIT $1
`

